#!/usr/bin/env node
/**
 * Expand the eval ground truth with power-tool cases (M5).
 *
 * Reads Firestore for diverse Woodnet + Sawmill Creek listings whose titles
 * match our M5 power-tool vocabulary (Table Saw, Band Saw, Jointer, Thickness
 * Planer, Lathe, Drill Press, Router, Miter Saw, Track Saw, Sander, Drum
 * Sander, Dust Collector, Domino, Biscuit Joiner, Workbench, CNC, etc.),
 * runs each through Opus 4.7 with high effort, and appends the new labels to
 * the existing `ground_truth.json` file.
 *
 * The hand-tool cases generated by the original bootstrap are preserved;
 * only new power-tool entries are added. Entries are keyed by doc_id so
 * re-running this script updates in place rather than duplicating.
 *
 * Usage:
 *   node functions/normalize/eval/bootstrap-powertools.js
 *   node functions/normalize/eval/bootstrap-powertools.js --size 25
 *   node functions/normalize/eval/bootstrap-powertools.js --dry-run
 */

const path = require('path');
const fs = require('fs');
const admin = require('firebase-admin');
const Anthropic = require('@anthropic-ai/sdk');

// Convenience env load (same pattern as bootstrap-truth.js).
(function loadLocalEnv() {
  if (process.env.ANTHROPIC_API_KEY) return;
  const envPath = path.resolve(__dirname, '..', '..', '.env');
  if (!fs.existsSync(envPath)) return;
  const text = fs.readFileSync(envPath, 'utf8');
  for (const rawLine of text.split('\n')) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq < 0) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    if (!(key in process.env)) process.env[key] = value;
  }
})();

const { SYSTEM_PROMPT } = require('../prompt');
const { CLASSIFY_TOOL } = require('../normalizer');
const { extractBrand, extractType } = require('../../ingest/heuristics');

const EVAL_DIR = __dirname;
const GROUND_TRUTH_PATH = path.join(EVAL_DIR, 'ground_truth.json');

const MODEL = 'claude-opus-4-7';
const MAX_TOKENS = 2048;

// Power-tool canonical types the seed should cover (M5). We stratify across
// these so the eval gets hit breadth, not all "Table Saw".
const POWER_TOOL_TYPES = [
  'Table Saw', 'Band Saw', 'Miter Saw', 'Jointer', 'Thickness Planer',
  'Lathe', 'Drill Press', 'Router', 'Track Saw', 'Circular Saw', 'Sander',
  'Drum Sander', 'Dust Collector', 'Air Compressor', 'Mortiser',
  'Scroll Saw', 'Domino', 'Biscuit Joiner', 'Drill', 'Impact Driver',
  'CNC', 'Workbench', 'Router Table',
];
const POWER_TOOL_TYPES_SET = new Set(POWER_TOOL_TYPES);

function parseArgs(argv) {
  const args = { size: 30, concurrency: 3, dryRun: false, perType: 2 };
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--size') args.size = Number(argv[++i]);
    else if (a.startsWith('--size=')) args.size = Number(a.slice('--size='.length));
    else if (a === '--per-type') args.perType = Number(argv[++i]);
    else if (a === '--concurrency') args.concurrency = Number(argv[++i]);
    else if (a === '--dry-run') args.dryRun = true;
  }
  return args;
}

function initAdmin() {
  if (admin.apps.length) return;
  const saPath = path.resolve(__dirname, '..', '..', 'service-account.json');
  try {
    admin.initializeApp({ credential: admin.credential.cert(require(saPath)) });
  } catch (e) {
    admin.initializeApp();
  }
}

async function sampleCandidates(db, perType, targetSize) {
  // Pull from the forum sources where power tools concentrate. Jim Bode and
  // Hyperkitten are hand-tool-dealer sources — little power-tool inventory.
  const sources = ['woodnet', 'sawmillcreek'];
  const all = [];
  for (const source of sources) {
    const snap = await db.collection('externalListings')
      .where('source', '==', source)
      .get();
    for (const doc of snap.docs) {
      const data = doc.data();
      all.push({ id: doc.id, ...data });
    }
  }
  console.log(`[bootstrap-powertools] loaded ${all.length} total listings from ${sources.join(', ')}`);

  // Run the updated heuristic to get a current type guess; keep only listings
  // whose guess is in the power-tool set.
  const byType = new Map();
  for (const d of all) {
    const title = d.title_raw || '';
    const desc = d.description_raw || '';
    const type = extractType(`${title} ${desc}`);
    if (!POWER_TOOL_TYPES_SET.has(type)) continue;
    if (!byType.has(type)) byType.set(type, []);
    byType.get(type).push({ ...d, _heuristic_type_m5: type });
  }

  // Fisher-Yates per bucket for run-to-run variety.
  for (const arr of byType.values()) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }

  const buckets = [...byType.entries()].sort((a, b) => b[1].length - a[1].length);
  console.log('[bootstrap-powertools] bucket depth:');
  for (const [t, arr] of buckets) console.log(`  ${t.padEnd(20)} ${arr.length}`);

  const picked = [];
  const pickedIds = new Set();

  // First pass: take perType from each bucket.
  for (const [type, arr] of buckets) {
    const take = Math.min(perType, arr.length);
    for (let i = 0; i < take; i++) {
      const item = arr[i];
      picked.push(item);
      pickedIds.add(item.id);
    }
  }

  // Second pass: top up from fullest buckets.
  if (picked.length < targetSize) {
    for (const [type, arr] of buckets) {
      if (picked.length >= targetSize) break;
      for (const item of arr) {
        if (picked.length >= targetSize) break;
        if (!pickedIds.has(item.id)) {
          picked.push(item);
          pickedIds.add(item.id);
        }
      }
    }
  }

  return picked.slice(0, targetSize);
}

function toSeedEntry(doc) {
  return {
    doc_id: doc.id,
    source: doc.source,
    source_id: doc.source_id,
    title_raw: doc.title_raw,
    truth: {
      canonical_brand: doc.heuristic_brand || 'Unknown',
      canonical_type: doc._heuristic_type_m5,
      canonical_model: null,
      canonical_size: null,
      era_estimate: null,
    },
    _heuristic_brand: doc.heuristic_brand,
    _heuristic_type: doc.heuristic_type,
    _heuristic_type_m5: doc._heuristic_type_m5,
    _tags: doc.tags,
  };
}

function buildUserMessage(entry, description) {
  const parts = [];
  parts.push(
    'You are generating ground-truth labels for a canonical-normalization eval.',
    'Be more careful than a production normalizer would be — this is the answer key.',
    'Prefer null over a guess when genuinely uncertain. When the model or era is',
    'clearly stated in the title or description, fill it in precisely.',
    '',
    `Title: ${entry.title_raw || '(missing)'}`
  );
  if (description) parts.push(`Description: ${description.slice(0, 1200)}`);
  if (entry._tags && entry._tags.length) parts.push(`Tags: ${entry._tags.slice(0, 10).join(', ')}`);
  if (entry._heuristic_brand) parts.push(`(Heuristic brand guess — ignore if unreliable: ${entry._heuristic_brand})`);
  if (entry._heuristic_type_m5) parts.push(`(Heuristic type guess — ignore if unreliable: ${entry._heuristic_type_m5})`);
  return parts.join('\n');
}

function computeReviewFlags(entry, predicted) {
  const flags = [];
  const seedBrand = entry.truth?.canonical_brand || null;
  if (seedBrand && seedBrand !== predicted.canonical_brand) {
    flags.push(`brand: heuristic=${seedBrand} vs opus=${predicted.canonical_brand}`);
  }
  if (seedBrand === 'Unknown' && predicted.canonical_brand !== 'Unknown') {
    flags.push(`brand: heuristic=Unknown but opus found ${predicted.canonical_brand}`);
  }
  const seedType = entry.truth?.canonical_type || null;
  if (seedType && seedType !== predicted.canonical_type) {
    flags.push(`type: heuristic=${seedType} vs opus=${predicted.canonical_type}`);
  }
  if (predicted.canonical_model) flags.push(`model inferred: "${predicted.canonical_model}" — verify against title`);
  if (predicted.era_estimate) flags.push(`era inferred: "${predicted.era_estimate}" — verify against title/description`);
  return flags;
}

async function runWithConcurrency(items, concurrency, worker) {
  const results = new Array(items.length);
  let next = 0;
  let done = 0;
  async function pump() {
    while (true) {
      const i = next++;
      if (i >= items.length) return;
      results[i] = await worker(items[i], i);
      done++;
      process.stdout.write(`\r[bootstrap-powertools] ${done}/${items.length} labeled`);
    }
  }
  await Promise.all(Array.from({ length: Math.min(concurrency, items.length) }, pump));
  process.stdout.write('\n');
  return results;
}

async function main() {
  const args = parseArgs(process.argv);
  initAdmin();
  const db = admin.firestore();

  const candidates = await sampleCandidates(db, args.perType, args.size);
  const candidateDocs = await Promise.all(candidates.map(async (c) => {
    // Pull full doc with description for the LLM.
    const descSnap = await db.collection('externalListingsRaw').doc(c.id).get();
    const rawBody = descSnap.exists ? descSnap.data().raw?.body_text : null;
    return { ...c, _description_for_llm: c.description_raw || rawBody || '' };
  }));
  const seeded = candidateDocs.map(toSeedEntry);

  if (args.dryRun) {
    console.log('\n[bootstrap-powertools] dry-run sample:');
    for (const s of seeded) {
      console.log(`  ${s._heuristic_type_m5.padEnd(20)} ${s.title_raw}`);
    }
    return;
  }

  if (!process.env.ANTHROPIC_API_KEY) {
    console.error('[bootstrap-powertools] ANTHROPIC_API_KEY not set');
    process.exit(2);
  }

  console.log(`\n[bootstrap-powertools] labeling ${seeded.length} power-tool listings with ${MODEL} (concurrency=${args.concurrency})`);

  const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
  const totals = { input: 0, output: 0, cacheCreate: 0, cacheRead: 0 };

  const results = await runWithConcurrency(seeded, args.concurrency, async (entry, idx) => {
    try {
      const description = candidateDocs[idx]._description_for_llm;
      const response = await client.messages.create({
        model: MODEL,
        max_tokens: MAX_TOKENS,
        output_config: { effort: 'high' },
        system: [
          { type: 'text', text: SYSTEM_PROMPT, cache_control: { type: 'ephemeral' } },
        ],
        tools: [CLASSIFY_TOOL],
        tool_choice: { type: 'tool', name: 'classify_listing' },
        messages: [{ role: 'user', content: buildUserMessage(entry, description) }],
      });
      totals.input += response.usage.input_tokens;
      totals.output += response.usage.output_tokens;
      totals.cacheCreate += response.usage.cache_creation_input_tokens || 0;
      totals.cacheRead += response.usage.cache_read_input_tokens || 0;
      const toolUse = response.content.find((b) => b.type === 'tool_use');
      if (!toolUse) return { ok: false, entry, error: `no tool_use (stop_reason=${response.stop_reason})` };
      return { ok: true, entry, predicted: toolUse.input };
    } catch (err) {
      return { ok: false, entry, error: err.message };
    }
  });

  const newEntries = [];
  const errored = [];
  for (const r of results) {
    if (!r.ok) {
      errored.push(r);
      newEntries.push({ ...r.entry, _bootstrap_error: r.error });
      continue;
    }
    const reviewFlags = computeReviewFlags(r.entry, r.predicted);
    newEntries.push({
      ...r.entry,
      truth: {
        canonical_brand: r.predicted.canonical_brand,
        canonical_type: r.predicted.canonical_type,
        canonical_model: r.predicted.canonical_model,
        canonical_size: r.predicted.canonical_size,
        era_estimate: r.predicted.era_estimate,
      },
      _bootstrap_review: reviewFlags,
      _cohort: 'powertools_m5',
    });
  }

  // Merge into existing ground_truth.json (append new doc_ids; update
  // in-place if already present).
  const existing = JSON.parse(fs.readFileSync(GROUND_TRUTH_PATH, 'utf8'));
  const existingById = new Map((existing.listings || []).map((l) => [l.doc_id, l]));
  for (const entry of newEntries) existingById.set(entry.doc_id, entry);
  existing.listings = [...existingById.values()];
  existing.count = existing.listings.length;
  existing.m5_expanded_at = new Date().toISOString();
  existing.m5_expanded_count = newEntries.length;

  const OPUS = { input: 5.0, output: 25.0, cacheWrite: 6.25, cacheRead: 0.5 };
  const cost =
    (totals.input * OPUS.input
      + totals.output * OPUS.output
      + totals.cacheCreate * OPUS.cacheWrite
      + totals.cacheRead * OPUS.cacheRead) / 1_000_000;

  fs.writeFileSync(GROUND_TRUTH_PATH, JSON.stringify(existing, null, 2), 'utf8');

  const reviewCount = newEntries.filter((l) => l._bootstrap_review && l._bootstrap_review.length > 0).length;
  console.log(`[bootstrap-powertools] appended ${newEntries.length} entries to ${GROUND_TRUTH_PATH}`);
  console.log(`[bootstrap-powertools] ${reviewCount} entries flagged for spot-check (non-empty _bootstrap_review)`);
  console.log(`[bootstrap-powertools] ${errored.length} errored (preserved with _bootstrap_error)`);
  console.log(`[bootstrap-powertools] tokens: input=${totals.input} output=${totals.output} cache_write=${totals.cacheCreate} cache_read=${totals.cacheRead}`);
  console.log(`[bootstrap-powertools] cost: $${cost.toFixed(4)}`);
  console.log(`[bootstrap-powertools] total ground_truth.json count: ${existing.count}`);
}

main().catch((e) => {
  console.error('\n[bootstrap-powertools] fatal:', e);
  process.exit(1);
});
